/**
 * Emitted when VAD detects end of speech (endpointing=vad only).
 */
export interface RealtimeVadSpeechEnd {
    event: "vad.speech_end";
    /** Zero-based utterance counter for the session */
    utterance_idx: number;
    /** VAD confidence (0.0–1.0) */
    confidence?: number | undefined;
}
